from pathlib import Path
import numpy as np
import soundfile as sf


_RT60_MEASURED_TOKEN = "exceeds_limit"


RT60_REJECT_UNMEASURED = "unmeasured"   # retry helps


RT60_REJECT_TOO_LIVE = "too_live"       # retry cannot help


RT60_REJECT_COPY = {
    RT60_REJECT_UNMEASURED: "We couldn't get a clear enough read from these claps.",
    RT60_REJECT_TOO_LIVE: (
        "Your room's echo is too strong for this kind of recording. "
        "Soft furnishings help — curtains, a rug, upholstered furniture — "
        "or try a smaller or more furnished room."),
}


def rt60_reject_kind(verdict: str | None, reason: str | None) -> str | None:
    """Which of the two RT60 refusals this is; None when it is not a refusal.

    Classifies from the CORE's disposition_reason, which is the only place the
    distinction exists. Anything that is not explicitly the measured-and-too-live token
    is treated as UNMEASURED, and that default is the safe one: it offers a retry. The
    failure mode it avoids is the expensive one — withholding a retry from someone whose
    claps merely needed redoing would strand them with no path at all.
    """
    if verdict not in ("FAIL", "ERROR"):
        return None
    if _RT60_MEASURED_TOKEN in (reason or ""):
        return RT60_REJECT_TOO_LIVE
    return RT60_REJECT_UNMEASURED


CLAP_COLLECT_N = 3          # §7.1 — usable claps that constitute support


CLAP_COLLECT_CAP = 10       # §5  — DETECTED claps, so a zero-yield room still terminates


def clap_usable_count(rec: dict | None) -> int:
    """Claps that actually SUPPORT the gate metric: valid AND carrying a 1 kHz value.

    Not `n_claps_valid` — validity is peak/crest/attack/clipping and a clap that fits
    badly still counts there. The gate metric is a median over claps with a non-None
    1 kHz reading, so this is the number that decides whether the measurement is
    supported.
    """
    claps = (rec or {}).get("claps") or []
    return sum(1 for c in claps
               if c.get("valid") and (c.get("rt60_per_band") or {}).get("1000") is not None)


def clap_collection_state(rec: dict | None, verdict: str | None,
                          reason: str | None) -> dict:
    """Should the contributor be asked for MORE claps? The one home for that decision.

    Returns `detected` / `usable` / `needed` / `cap` / `collect_more`, and every clap
    entry point reads it rather than re-deriving the rule — the conditional-stage build
    established that a rule taught at N call sites is N chances to strand somebody.

    `collect_more` is TRUE only when the take is UNMEASURED and under the cap. The two
    exclusions are the whole subtlety:
      * a TOO_LIVE refusal has a MEASUREMENT — the room is genuinely too reverberant, so
        more claps cannot change the answer and asking for them is the tail-chase the
        directional-coaching work exists to stop.
      * a PASS (including an AB-7' dry-room pass, which carries NO metric by construction)
        already has its answer. Asking for more claps there would be asking a question
        that has been answered.
    """
    claps = (rec or {}).get("claps") or []
    detected = len(claps)
    usable = clap_usable_count(rec)
    kind = rt60_reject_kind(verdict, reason)
    collect_more = (kind == RT60_REJECT_UNMEASURED
                    and usable < CLAP_COLLECT_N
                    and detected < CLAP_COLLECT_CAP)
    return {"detected": detected, "usable": usable, "needed": CLAP_COLLECT_N,
            "cap": CLAP_COLLECT_CAP, "collect_more": collect_more}


def concat_clap_takes(previous: Path | str, addition: Path | str,
                      out_path: Path | str) -> Path:
    """Join an earlier clap take with a newly recorded one, for §7.2 append.

    SAFE BECAUSE THE COPY ALREADY ASKS FOR A 3 s SILENT TAIL: the last clap of the
    earlier take has its full decay before the splice, so the join cannot truncate a
    decay the fit then measures. `detect_claps` finds peaks on the raw sample array with
    a minimum inter-clap distance, so it is position-agnostic and the splice itself is
    not a feature it can trip on.

    Both takes come from the same capture chain in the same session, so sample rate and
    channel count match by construction; mismatch is a programming error, not a
    contributor state, and raises rather than silently resampling.
    """
    a, sr_a = sf.read(str(previous), always_2d=True)
    b, sr_b = sf.read(str(addition), always_2d=True)
    if sr_a != sr_b or a.shape[1] != b.shape[1]:
        raise ValueError(
            f"clap take mismatch: {sr_a}Hz/{a.shape[1]}ch vs {sr_b}Hz/{b.shape[1]}ch")
    sf.write(str(out_path), np.concatenate([a, b], axis=0), sr_a,
             subtype=sf.info(str(previous)).subtype)
    return Path(out_path)
